COMMENT ON COLUMN "auth"."sessions"."mfa_at" IS 'When its owner last completed a second factor.';

COMMENT ON COLUMN "auth"."sessions"."last_seen_at" IS 'When the session was last used, to the minute.';

COMMENT ON COLUMN "auth"."sessions"."idle_expires_at" IS 'When it ends unless it''s used before then.';

COMMENT ON COLUMN "auth"."sessions"."expires_at" IS 'When it ends however often it''s used.';

COMMENT ON COLUMN "auth"."sessions"."device" IS 'What signed in, such as "Firefox on macOS", for the list of devices.';

COMMENT ON COLUMN "auth"."sessions"."revoked_at" IS 'When it was signed out or revoked.';

CREATE TABLE "auth"."totp" (
	"id" uuid NOT NULL,
	"account_id" uuid NOT NULL,
	"secret" bytea NOT NULL,
	"confirmed_at" timestamptz,
	"last_used_step" bigint,
	"created_at" timestamptz NOT NULL,
	CONSTRAINT "auth_totp_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "auth_totp_account_id_key" ON "auth"."totp" ("account_id");

COMMENT ON TABLE "auth"."totp" IS 'An account''s authenticator app: the TOTP secret it shares with the
server. The secret is encrypted with the server''s keys, so a copy of the
database can''t produce codes, and bound to its account.';

COMMENT ON COLUMN "auth"."totp"."account_id" IS 'One authenticator per account.';

COMMENT ON COLUMN "auth"."totp"."secret" IS 'AES-256-GCM-SIV under the newest key, with the key''s ID.';

COMMENT ON COLUMN "auth"."totp"."confirmed_at" IS 'When a code from the app first matched. Until then the app isn''t
trusted to sign in with.';

COMMENT ON COLUMN "auth"."totp"."last_used_step" IS 'The last 30-second step whose code was used, so no code works twice.';

CREATE TABLE "auth"."wallets" (
	"id" uuid NOT NULL,
	"account_id" uuid NOT NULL,
	"chain" varchar(32) NOT NULL,
	"address" text NOT NULL,
	"label" varchar(100),
	"can_sign_in" boolean NOT NULL,
	"is_public" boolean NOT NULL,
	"verified_at" timestamptz NOT NULL,
	"last_proved_at" timestamptz NOT NULL,
	"proof" varchar(4096) NOT NULL,
	"proof_signature" text NOT NULL,
	"created_at" timestamptz NOT NULL,
	CONSTRAINT "auth_wallets_pkey" PRIMARY KEY ("id"),
	CONSTRAINT "auth_wallets_address_length" CHECK (char_length("address") >= 32 AND char_length("address") <= 44),
	CONSTRAINT "auth_wallets_address_pattern" CHECK ("address" ~ '^[1-9A-HJ-NP-Za-km-z]+$'),
	CONSTRAINT "auth_wallets_proof_signature_length" CHECK (char_length("proof_signature") >= 64 AND char_length("proof_signature") <= 88),
	CONSTRAINT "auth_wallets_proof_signature_pattern" CHECK ("proof_signature" ~ '^[1-9A-HJ-NP-Za-km-z]+$')
);

CREATE INDEX "auth_wallets_account_id_idx" ON "auth"."wallets" ("account_id");

CREATE UNIQUE INDEX "auth_wallets_chain_address_key" ON "auth"."wallets" ("chain", "address");

COMMENT ON TABLE "auth"."wallets" IS 'A wallet linked to an account, with proof that the account''s owner
controls it: a Sign-In With Solana message signed by its key. A wallet
belongs to one account. It''s private unless its owner shows it, and
signs in only when its owner turns that on.';

COMMENT ON COLUMN "auth"."wallets"."chain" IS 'The chain: `solana`.';

COMMENT ON COLUMN "auth"."wallets"."address" IS 'The address.';

COMMENT ON COLUMN "auth"."wallets"."label" IS 'What the person calls it, such as "Treasury".';

COMMENT ON COLUMN "auth"."wallets"."can_sign_in" IS 'Whether it may sign in to the account. Off until its owner turns it
on.';

COMMENT ON COLUMN "auth"."wallets"."is_public" IS 'Whether it shows on its owner''s public profile.';

COMMENT ON COLUMN "auth"."wallets"."verified_at" IS 'When it was linked.';

COMMENT ON COLUMN "auth"."wallets"."last_proved_at" IS 'When it last signed a proof.';

COMMENT ON COLUMN "auth"."wallets"."proof" IS 'The latest signed message, kept for audit.';

COMMENT ON COLUMN "auth"."wallets"."proof_signature" IS 'The message''s signature.';

CREATE TABLE "idp"."assertions" (
	"id" uuid NOT NULL,
	"client_id" uuid NOT NULL,
	"jti_hash" bytea NOT NULL,
	"expires_at" timestamptz NOT NULL,
	CONSTRAINT "idp_assertions_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "idp_assertions_jti_hash_key" ON "idp"."assertions" ("jti_hash");

CREATE INDEX "idp_assertions_expires_at_idx" ON "idp"."assertions" ("expires_at");

COMMENT ON TABLE "idp"."assertions" IS 'A `private_key_jwt` assertion an app authenticated with, kept until it
expires so it can''t be used twice.';

COMMENT ON COLUMN "idp"."assertions"."jti_hash" IS 'The assertion''s `jti`, hashed with the client''s ID.';

CREATE TABLE "idp"."authorizations" (
	"id" uuid NOT NULL,
	"client_id" uuid NOT NULL,
	"account_id" uuid NOT NULL,
	"redirect_uri" varchar(2048) NOT NULL,
	"scopes" jsonb NOT NULL,
	"state" varchar(2048),
	"nonce" varchar(2048),
	"id_token_claims" jsonb NOT NULL,
	"code_challenge" varchar(128) NOT NULL,
	"auth_time" timestamptz NOT NULL,
	"consent_hash" bytea,
	"code_hash" bytea,
	"expires_at" timestamptz NOT NULL,
	"used_at" timestamptz,
	"family_id" uuid,
	"created_at" timestamptz NOT NULL,
	CONSTRAINT "idp_authorizations_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "idp_authorizations_consent_hash_key" ON "idp"."authorizations" ("consent_hash");

CREATE UNIQUE INDEX "idp_authorizations_code_hash_key" ON "idp"."authorizations" ("code_hash");

CREATE INDEX "idp_authorizations_expires_at_idx" ON "idp"."authorizations" ("expires_at");

COMMENT ON TABLE "idp"."authorizations" IS 'An authorization request: waiting for consent, then an authorization
code, then used. Codes last a minute and work once.';

COMMENT ON COLUMN "idp"."authorizations"."id_token_claims" IS 'Claims asked for in the ID token with the `claims` parameter.';

COMMENT ON COLUMN "idp"."authorizations"."code_challenge" IS 'The PKCE `S256` challenge.';

COMMENT ON COLUMN "idp"."authorizations"."consent_hash" IS 'The handle the consent screen reads it by, while it waits.';

COMMENT ON COLUMN "idp"."authorizations"."code_hash" IS 'The authorization code, once consent is given.';

COMMENT ON COLUMN "idp"."authorizations"."used_at" IS 'When it was answered or its code traded.';

COMMENT ON COLUMN "idp"."authorizations"."family_id" IS 'The family its code started, which a replayed code ends.';

CREATE TABLE "idp"."clients" (
	"id" uuid NOT NULL,
	"client_id" varchar(64) NOT NULL,
	"name" text NOT NULL,
	"auth_method" text NOT NULL,
	"secret_hash" bytea,
	"jwks" jsonb,
	"grant_types" jsonb NOT NULL,
	"id_token_alg" text NOT NULL,
	"redirect_uris" jsonb NOT NULL,
	"post_logout_redirect_uris" jsonb NOT NULL,
	"scopes" jsonb NOT NULL,
	"first_party" boolean NOT NULL,
	"introspection" boolean NOT NULL,
	"subject_salt" bytea NOT NULL,
	"owner_id" uuid,
	"dpop_bound" boolean NOT NULL DEFAULT false,
	"registration_hash" bytea,
	"created_at" timestamptz NOT NULL,
	CONSTRAINT "idp_clients_pkey" PRIMARY KEY ("id"),
	CONSTRAINT "idp_clients_name_length" CHECK (char_length("name") >= 1 AND char_length("name") <= 100),
	CONSTRAINT "idp_clients_auth_method_values" CHECK ("auth_method" IN ('none', 'client_secret_basic', 'client_secret_post', 'private_key_jwt')),
	CONSTRAINT "idp_clients_id_token_alg_values" CHECK ("id_token_alg" IN ('ES256', 'RS256'))
);

CREATE UNIQUE INDEX "idp_clients_client_id_key" ON "idp"."clients" ("client_id");

CREATE UNIQUE INDEX "idp_clients_registration_hash_key" ON "idp"."clients" ("registration_hash");

CREATE INDEX "idp_clients_owner_id_idx" ON "idp"."clients" ("owner_id");

COMMENT ON TABLE "idp"."clients" IS 'An app that may ask people to sign in with yours. Operators register
them with `lk auth idp client add`; with the developer portal on, people
register their own, which they alone see.';

COMMENT ON COLUMN "idp"."clients"."client_id" IS 'The public identifier the app sends as `client_id`.';

COMMENT ON COLUMN "idp"."clients"."name" IS 'The app''s name, as the consent screen shows it.';

COMMENT ON COLUMN "idp"."clients"."secret_hash" IS 'The SHA-256 of the client secret, for a confidential client.';

COMMENT ON COLUMN "idp"."clients"."jwks" IS 'The public keys a `private_key_jwt` client signs with, as a JWK set.';

COMMENT ON COLUMN "idp"."clients"."grant_types" IS 'How it gets tokens.';

COMMENT ON COLUMN "idp"."clients"."id_token_alg" IS 'How its ID tokens are signed.';

COMMENT ON COLUMN "idp"."clients"."redirect_uris" IS 'Where codes may be sent, compared exactly.';

COMMENT ON COLUMN "idp"."clients"."post_logout_redirect_uris" IS 'Where people may be sent after signing out, compared exactly.';

COMMENT ON COLUMN "idp"."clients"."scopes" IS 'The scopes the app may ask for.';

COMMENT ON COLUMN "idp"."clients"."first_party" IS 'One of your own apps: it sees the account ID as `sub` instead of a
pairwise one, and needs no consent.';

COMMENT ON COLUMN "idp"."clients"."introspection" IS 'Whether it may introspect tokens issued to other apps, as a resource
server does.';

COMMENT ON COLUMN "idp"."clients"."subject_salt" IS 'Mixed into the pairwise `sub` each account gets for this app, so two
apps can''t match up their users.';

COMMENT ON COLUMN "idp"."clients"."owner_id" IS 'Who registered it in the developer portal; `None` for an app the
operator registered.';

COMMENT ON COLUMN "idp"."clients"."dpop_bound" IS 'Whether every access token it gets must be bound to a key it holds,
with DPoP (RFC 9449), so a stolen token is useless without the key.';

COMMENT ON COLUMN "idp"."clients"."registration_hash" IS 'The SHA-256 of the token that manages it, for an app that registered
itself through dynamic registration (RFC 7591 and 7592).';

CREATE TABLE "idp"."device_codes" (
	"id" uuid NOT NULL,
	"client_id" uuid NOT NULL,
	"device_hash" bytea NOT NULL,
	"user_code_hash" bytea NOT NULL,
	"scopes" jsonb NOT NULL,
	"account_id" uuid,
	"auth_time" timestamptz,
	"approved" boolean,
	"interval" integer NOT NULL,
	"polled_at" timestamptz,
	"expires_at" timestamptz NOT NULL,
	"used_at" timestamptz,
	"family_id" uuid,
	"created_at" timestamptz NOT NULL,
	CONSTRAINT "idp_device_codes_pkey" PRIMARY KEY ("id"),
	CONSTRAINT "idp_device_codes_interval_range" CHECK ("interval" >= 1)
);

CREATE UNIQUE INDEX "idp_device_codes_device_hash_key" ON "idp"."device_codes" ("device_hash");

CREATE UNIQUE INDEX "idp_device_codes_user_code_hash_key" ON "idp"."device_codes" ("user_code_hash");

CREATE INDEX "idp_device_codes_expires_at_idx" ON "idp"."device_codes" ("expires_at");

COMMENT ON TABLE "idp"."device_codes" IS 'A sign-in started on a device with no browser, such as a CLI or a TV
(RFC 8628): it shows a short code, someone enters it on their phone or
computer and approves, and the device''s polling then gets tokens.';

COMMENT ON COLUMN "idp"."device_codes"."device_hash" IS 'The secret the device polls with, hashed.';

COMMENT ON COLUMN "idp"."device_codes"."user_code_hash" IS 'The code people type, hashed.';

COMMENT ON COLUMN "idp"."device_codes"."scopes" IS 'What the device asked to do.';

COMMENT ON COLUMN "idp"."device_codes"."account_id" IS 'Who approved or refused it.';

COMMENT ON COLUMN "idp"."device_codes"."auth_time" IS 'When they last proved who they are, once they approved.';

COMMENT ON COLUMN "idp"."device_codes"."approved" IS 'Whether they approved, once they answered.';

COMMENT ON COLUMN "idp"."device_codes"."interval" IS 'Seconds the device must wait between polls.';

COMMENT ON COLUMN "idp"."device_codes"."polled_at" IS 'When the device last polled.';

COMMENT ON COLUMN "idp"."device_codes"."used_at" IS 'When the device traded it for tokens.';

COMMENT ON COLUMN "idp"."device_codes"."family_id" IS 'The family it started, which a replayed device code ends.';

CREATE TABLE "idp"."dpop_proofs" (
	"id" uuid NOT NULL,
	"jti_hash" bytea NOT NULL,
	"expires_at" timestamptz NOT NULL,
	CONSTRAINT "idp_dpop_proofs_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "idp_dpop_proofs_jti_hash_key" ON "idp"."dpop_proofs" ("jti_hash");

CREATE INDEX "idp_dpop_proofs_expires_at_idx" ON "idp"."dpop_proofs" ("expires_at");

COMMENT ON TABLE "idp"."dpop_proofs" IS 'A DPoP proof (RFC 9449) already presented, kept until it''s too old to be
accepted anyway, so none works twice.';

COMMENT ON COLUMN "idp"."dpop_proofs"."jti_hash" IS 'The proof''s `jti`, hashed with its key''s thumbprint.';

CREATE TABLE "idp"."families" (
	"id" uuid NOT NULL,
	"grant_id" uuid,
	"account_id" uuid,
	"client_id" uuid NOT NULL,
	"scopes" jsonb NOT NULL,
	"id_token_claims" jsonb NOT NULL,
	"auth_time" timestamptz NOT NULL,
	"expires_at" timestamptz NOT NULL,
	"revoked_at" timestamptz,
	"jkt" varchar(64),
	"created_at" timestamptz NOT NULL,
	CONSTRAINT "idp_families_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "idp_families_account_id_idx" ON "idp"."families" ("account_id");

CREATE INDEX "idp_families_expires_at_idx" ON "idp"."families" ("expires_at");

COMMENT ON TABLE "idp"."families" IS 'One sign-in of an app: the refresh tokens that descend from one
authorization code or device code. A refresh token presented twice ends
the whole family, since one of the two holders stole it.

An app acting as itself (`client_credentials`) gets a family with no
person, grant or refresh token, so its access tokens can be revoked
too.';

COMMENT ON COLUMN "idp"."families"."scopes" IS 'The scopes its tokens may carry.';

COMMENT ON COLUMN "idp"."families"."id_token_claims" IS 'Claims the app asked to find in its ID tokens with the `claims`
parameter, such as `email`. Only claims its scopes release appear.';

COMMENT ON COLUMN "idp"."families"."auth_time" IS 'When the person last proved who they are, as `auth_time` says.';

COMMENT ON COLUMN "idp"."families"."expires_at" IS 'When its refresh tokens stop working however often they''re used.';

COMMENT ON COLUMN "idp"."families"."revoked_at" IS 'When it was revoked, signed out, or ended by a reused token.';

COMMENT ON COLUMN "idp"."families"."jkt" IS 'The RFC 7638 thumbprint of the DPoP key its refresh tokens are bound
to, for a public app that started it with a DPoP proof.';

CREATE TABLE "idp"."grants" (
	"id" uuid NOT NULL,
	"account_id" uuid NOT NULL,
	"client_id" uuid NOT NULL,
	"scopes" jsonb NOT NULL,
	"created_at" timestamptz NOT NULL,
	"updated_at" timestamptz NOT NULL,
	"last_used_at" timestamptz,
	CONSTRAINT "idp_grants_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "idp_grants_account_id_client_id_key" ON "idp"."grants" ("account_id", "client_id");

COMMENT ON TABLE "idp"."grants" IS 'What a person let an app do: the scopes they consented to. One per
account and app; revoking it ends every token the app holds for them.';

COMMENT ON COLUMN "idp"."grants"."scopes" IS 'Every scope they consented to.';

COMMENT ON COLUMN "idp"."grants"."updated_at" IS 'When they last consented to more.';

COMMENT ON COLUMN "idp"."grants"."last_used_at" IS 'When the app last refreshed its tokens.';

CREATE TABLE "idp"."pushed_requests" (
	"id" uuid NOT NULL,
	"client_id" uuid NOT NULL,
	"handle_hash" bytea NOT NULL,
	"request" jsonb NOT NULL,
	"expires_at" timestamptz NOT NULL,
	"created_at" timestamptz NOT NULL,
	CONSTRAINT "idp_pushed_requests_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "idp_pushed_requests_handle_hash_key" ON "idp"."pushed_requests" ("handle_hash");

CREATE INDEX "idp_pushed_requests_expires_at_idx" ON "idp"."pushed_requests" ("expires_at");

COMMENT ON TABLE "idp"."pushed_requests" IS 'An authorization request an app pushed ahead of sending the browser
(RFC 9126), so its parameters travel server to server rather than
through the address bar. It works once, and soon expires.';

COMMENT ON COLUMN "idp"."pushed_requests"."handle_hash" IS 'The `request_uri` handle, hashed.';

COMMENT ON COLUMN "idp"."pushed_requests"."request" IS 'The request''s parameters.';

CREATE TABLE "idp"."refresh_tokens" (
	"id" uuid NOT NULL,
	"family_id" uuid NOT NULL,
	"token_hash" bytea NOT NULL,
	"used_at" timestamptz,
	"created_at" timestamptz NOT NULL,
	CONSTRAINT "idp_refresh_tokens_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "idp_refresh_tokens_token_hash_key" ON "idp"."refresh_tokens" ("token_hash");

COMMENT ON TABLE "idp"."refresh_tokens" IS 'A refresh token. Only its SHA-256 hash is kept, and it works once.';

COMMENT ON COLUMN "idp"."refresh_tokens"."used_at" IS 'When it was traded for new tokens.';

CREATE TABLE "idp"."signing_keys" (
	"id" uuid NOT NULL,
	"kid" varchar(64) NOT NULL,
	"algorithm" text NOT NULL,
	"derived_from" varchar(64),
	"x" varchar(64),
	"y" varchar(64),
	"n" varchar(1400),
	"e" varchar(16),
	"retires_at" timestamptz NOT NULL,
	"expires_at" timestamptz NOT NULL,
	"created_at" timestamptz NOT NULL,
	CONSTRAINT "idp_signing_keys_pkey" PRIMARY KEY ("id"),
	CONSTRAINT "idp_signing_keys_algorithm_values" CHECK ("algorithm" IN ('ES256', 'RS256'))
);

CREATE UNIQUE INDEX "idp_signing_keys_kid_key" ON "idp"."signing_keys" ("kid");

COMMENT ON TABLE "idp"."signing_keys" IS 'A key that signs ID and access tokens. The database keeps only its
public half. An ES256 key''s private half is derived from one of the
server''s `AUTH_ENCRYPTION_KEYS` whenever it''s needed; an RS256 key''s is
the RSA key the server was given.';

COMMENT ON COLUMN "idp"."signing_keys"."kid" IS 'The key ID tokens name in their header.';

COMMENT ON COLUMN "idp"."signing_keys"."derived_from" IS 'The ID of the server key an ES256 key is derived from.';

COMMENT ON COLUMN "idp"."signing_keys"."x" IS 'An ES256 key''s P-256 coordinates, in base64url.';

COMMENT ON COLUMN "idp"."signing_keys"."n" IS 'An RS256 key''s modulus and exponent, in base64url.';

COMMENT ON COLUMN "idp"."signing_keys"."retires_at" IS 'When it stops signing new tokens.';

COMMENT ON COLUMN "idp"."signing_keys"."expires_at" IS 'When it leaves the published key set, after every token it signed
has expired.';

CREATE TABLE "live"."changes" (
	"seq" bigint NOT NULL,
	"txid" bigint,
	"version" bigint,
	"table_name" text NOT NULL,
	"op" text NOT NULL,
	"key" jsonb NOT NULL,
	"old" jsonb,
	"new" jsonb,
	"changed" jsonb NOT NULL,
	CONSTRAINT "live_changes_pkey" PRIMARY KEY ("seq"),
	CONSTRAINT "live_changes_op_values" CHECK ("op" IN ('I', 'U', 'D'))
) PARTITION BY RANGE ("seq");

CREATE TABLE "live"."changes_default" PARTITION OF "live"."changes" DEFAULT;

CREATE INDEX "live_changes_txid_idx" ON "live"."changes" ("txid");

CREATE INDEX "live_changes_version_idx" ON "live"."changes" ("version");

COMMENT ON TABLE "live"."changes" IS '`live.changes`: one row per written row of a live table.';

COMMENT ON COLUMN "live"."changes"."seq" IS 'The change''s place among the database''s changes.';

COMMENT ON COLUMN "live"."changes"."txid" IS 'The Postgres transaction that wrote it, which joins it to its commit.';

COMMENT ON COLUMN "live"."changes"."version" IS 'SQLite: the commit''s version, set just before the commit.';

COMMENT ON COLUMN "live"."changes"."table_name" IS 'The changed table, with its namespace: `messages` or `billing.invoices`.';

COMMENT ON COLUMN "live"."changes"."op" IS 'What the write did.';

COMMENT ON COLUMN "live"."changes"."key" IS 'The changed row''s key, in key column order.';

COMMENT ON COLUMN "live"."changes"."old" IS 'The row before an update or delete, without `secret` and
`live = skip` columns.';

COMMENT ON COLUMN "live"."changes"."new" IS 'The row after an insert or update, without those columns.';

COMMENT ON COLUMN "live"."changes"."changed" IS 'For an update, every column whose value changed; empty otherwise.';

CREATE TABLE "live"."commits" (
	"version" bigint NOT NULL,
	"txid" bigint,
	"committed_at" timestamptz NOT NULL,
	"actor" uuid,
	"origin" text NOT NULL,
	"lsn" bigint,
	CONSTRAINT "live_commits_pkey" PRIMARY KEY ("version")
) PARTITION BY RANGE ("version");

CREATE TABLE "live"."commits_default" PARTITION OF "live"."commits" DEFAULT;

CREATE INDEX "live_commits_txid_idx" ON "live"."commits" ("txid");

COMMENT ON TABLE "live"."commits" IS '`live.commits`: one row per committed transaction that wrote a live
table.';

COMMENT ON COLUMN "live"."commits"."version" IS 'The transaction''s place in the version line. Gaps are transactions
that rolled back after taking a version, which never become visible.';

COMMENT ON COLUMN "live"."commits"."txid" IS 'The Postgres transaction ID, which joins the commit to its changes.
`None` on SQLite.';

COMMENT ON COLUMN "live"."commits"."committed_at" IS 'When the transaction committed.';

COMMENT ON COLUMN "live"."commits"."actor" IS 'Who made the change, when the transaction said.';

COMMENT ON COLUMN "live"."commits"."origin" IS 'What made it: what the transaction said, such as an operation''s
name, or `sql`.';

COMMENT ON COLUMN "live"."commits"."lsn" IS 'Replication capture: where the commit''s record starts in Postgres''s
write-ahead log, which orders commits as the database committed them.
`None` for commits captured by triggers.';

CREATE TABLE "live"."pending" (
	"txid" bigint NOT NULL,
	CONSTRAINT "live_pending_pkey" PRIMARY KEY ("txid")
);

COMMENT ON TABLE "live"."pending" IS '`live.pending`, Postgres only: the transactions waiting for a version at
commit.';

COMMENT ON COLUMN "live"."pending"."txid" IS 'The transaction''s ID.';

CREATE TABLE "rpc"."inbox" (
	"id" uuid NOT NULL,
	"account" varchar(64) NOT NULL,
	"title" varchar(255) NOT NULL,
	"body" varchar(4000) NOT NULL,
	"link" varchar(2000),
	"action" jsonb,
	"kind" varchar(32) NOT NULL,
	"read_at" timestamptz,
	"created_at" timestamptz NOT NULL,
	CONSTRAINT "rpc_inbox_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "rpc_inbox_account_created_at_idx" ON "rpc"."inbox" ("account", "created_at");

COMMENT ON TABLE "rpc"."inbox" IS 'One notice in someone''s inbox, in the `rpc` pack''s `inbox` table.

Its policies let each account read and mark read only its own notices;
only server code writes them, through `cx.notify(...)`.';

COMMENT ON COLUMN "rpc"."inbox"."account" IS 'Whose notice it is: their account''s UUID.';

COMMENT ON COLUMN "rpc"."inbox"."action" IS 'The button on it.';

COMMENT ON COLUMN "rpc"."inbox"."kind" IS '`info`, `success`, `warning`, or `error`.';

COMMENT ON COLUMN "rpc"."inbox"."read_at" IS 'When its owner read it.';

CREATE TABLE "rpc"."jobs" (
	"id" uuid NOT NULL,
	"key" varchar(255),
	"name" varchar(255) NOT NULL,
	"queue" varchar(255) NOT NULL,
	"arguments" jsonb NOT NULL,
	"owner" varchar(64) NOT NULL,
	"viewer" varchar(64) NOT NULL,
	"visibility" text NOT NULL,
	"serial_key" varchar(512),
	"state" text NOT NULL,
	"attempts" bigint NOT NULL,
	"max_attempts" bigint NOT NULL,
	"priority" integer NOT NULL,
	"run_at" timestamptz NOT NULL,
	"deadline_at" timestamptz,
	"started_at" timestamptz,
	"finished_at" timestamptz,
	"locked_until" timestamptz,
	"result" jsonb,
	"error" varchar(2000),
	"progress" varchar(500),
	"fraction" double precision,
	"steps" jsonb NOT NULL,
	"cancel_requested" boolean NOT NULL,
	"failure_pending" boolean NOT NULL,
	"created_at" timestamptz NOT NULL,
	CONSTRAINT "rpc_jobs_pkey" PRIMARY KEY ("id"),
	CONSTRAINT "rpc_jobs_visibility_values" CHECK ("visibility" IN ('owner', 'signed_in', 'everyone')),
	CONSTRAINT "rpc_jobs_state_values" CHECK ("state" IN ('pending', 'running', 'done', 'failed', 'cancelled'))
);

CREATE UNIQUE INDEX "rpc_jobs_key_key" ON "rpc"."jobs" ("key");

CREATE INDEX "rpc_jobs_state_run_at_idx" ON "rpc"."jobs" ("state", "run_at");

CREATE INDEX "rpc_jobs_locked_until_idx" ON "rpc"."jobs" ("locked_until");

CREATE INDEX "rpc_jobs_queue_state_idx" ON "rpc"."jobs" ("queue", "state");

CREATE INDEX "rpc_jobs_serial_key_state_idx" ON "rpc"."jobs" ("serial_key", "state");

CREATE INDEX "rpc_jobs_finished_at_idx" ON "rpc"."jobs" ("finished_at");

COMMENT ON TABLE "rpc"."jobs" IS 'One enqueued job, in the `rpc` pack''s `jobs` table.

It''s a live table: a client follows a job with
[`use_job`](crate::client::use_job), and the hub sends each change. Its
policies show a job to the account that enqueued it, and to whoever
`#[rpc::job(visible_to = ...)]` names, and let only the owner change it.';

COMMENT ON COLUMN "rpc"."jobs"."key" IS 'The app''s idempotency key, if it gave one: enqueuing it again returns
the same job, until the job is pruned.';

COMMENT ON COLUMN "rpc"."jobs"."name" IS 'The job''s name.';

COMMENT ON COLUMN "rpc"."jobs"."queue" IS 'Its queue.';

COMMENT ON COLUMN "rpc"."jobs"."arguments" IS 'The arguments, as JSON.';

COMMENT ON COLUMN "rpc"."jobs"."owner" IS 'The account that enqueued it, as a UUID, or empty when nobody signed
in did.';

COMMENT ON COLUMN "rpc"."jobs"."viewer" IS 'Another account that may read it, from `visible_to = argument`, or
empty.';

COMMENT ON COLUMN "rpc"."jobs"."visibility" IS 'Who else may read it.';

COMMENT ON COLUMN "rpc"."jobs"."serial_key" IS 'The job''s name and its `serialize_by` argument: at most one job with
a key runs at a time.';

COMMENT ON COLUMN "rpc"."jobs"."attempts" IS 'How many times a worker has started it.';

COMMENT ON COLUMN "rpc"."jobs"."max_attempts" IS 'How many starts it gets before it fails.';

COMMENT ON COLUMN "rpc"."jobs"."priority" IS 'Higher runs first.';

COMMENT ON COLUMN "rpc"."jobs"."run_at" IS 'Not before this instant.';

COMMENT ON COLUMN "rpc"."jobs"."deadline_at" IS 'No attempt starts after this instant.';

COMMENT ON COLUMN "rpc"."jobs"."started_at" IS 'When a worker last started it.';

COMMENT ON COLUMN "rpc"."jobs"."finished_at" IS 'When it reached `done`, `failed`, or `cancelled`.';

COMMENT ON COLUMN "rpc"."jobs"."locked_until" IS 'Until when the running worker holds it; `None` when no one does.';

COMMENT ON COLUMN "rpc"."jobs"."result" IS 'What the body returned, as JSON.';

COMMENT ON COLUMN "rpc"."jobs"."error" IS 'Why the last attempt failed.';

COMMENT ON COLUMN "rpc"."jobs"."progress" IS 'What it last said it was doing.';

COMMENT ON COLUMN "rpc"."jobs"."fraction" IS 'How far along it last said it was, from 0 to 1.';

COMMENT ON COLUMN "rpc"."jobs"."steps" IS 'The results of the steps it finished, by name.';

COMMENT ON COLUMN "rpc"."jobs"."cancel_requested" IS 'Someone asked it to stop.';

COMMENT ON COLUMN "rpc"."jobs"."failure_pending" IS 'It failed, and its `on_failure` mutation hasn''t run yet.';

CREATE TABLE "rpc"."receipts" (
	"id" uuid NOT NULL,
	"owner" varchar(255) NOT NULL,
	"request_id" varchar(255) NOT NULL,
	"operation" varchar(255) NOT NULL,
	"arguments" varchar(64) NOT NULL,
	"result" jsonb NOT NULL,
	"created_at" timestamptz NOT NULL,
	CONSTRAINT "rpc_receipts_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "rpc_receipts_created_at_idx" ON "rpc"."receipts" ("created_at");

CREATE UNIQUE INDEX "rpc_receipts_owner_request_id_key" ON "rpc"."receipts" ("owner", "request_id");

COMMENT ON TABLE "rpc"."receipts" IS 'One mutation call that ran with a request ID, and what it returned.

Each caller sees only their own receipts: the policy compares
[`owner`](Self::owner) with the [`ReceiptOwner`] the RPC adds to the
context it runs a mutation in.';

COMMENT ON COLUMN "rpc"."receipts"."owner" IS 'Who called: their [`Identity::caller`](super::Identity::caller), such
as a session ID, or [`ANONYMOUS`] for anonymous callers.';

COMMENT ON COLUMN "rpc"."receipts"."request_id" IS 'The ID the call came with.';

COMMENT ON COLUMN "rpc"."receipts"."operation" IS 'The operation''s name.';

COMMENT ON COLUMN "rpc"."receipts"."arguments" IS 'A SHA-256 of the operation''s name and arguments, in hex: a repeat
with the same request ID and other arguments is refused rather than
answered with another call''s result.';

COMMENT ON COLUMN "rpc"."receipts"."result" IS 'What the call returned, as JSON.';

CREATE SEQUENCE "live"."change_seq";

CREATE SEQUENCE "live"."version_seq";

CREATE OR REPLACE FUNCTION "live"."capture"() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $leptoskit$
DECLARE
	captured_table text := TG_ARGV[0];
	key_columns text[] := string_to_array(TG_ARGV[1], ',');
	copied_columns text[] := TG_ARGV[2:TG_NARGS - 1];
	current_txid bigint := pg_current_xact_id()::text::bigint;
	old_row jsonb;
	new_row jsonb;
	changed_columns jsonb := '[]'::jsonb;
BEGIN
	IF TG_OP <> 'INSERT' THEN
		old_row := to_jsonb(OLD);
	END IF;

	IF TG_OP <> 'DELETE' THEN
		new_row := to_jsonb(NEW);
	END IF;

	IF TG_OP = 'UPDATE' THEN
		SELECT coalesce(jsonb_agg(entry.key ORDER BY entry.key), '[]'::jsonb)
		INTO changed_columns
		FROM jsonb_each(new_row) AS entry
		WHERE entry.value IS DISTINCT FROM old_row -> entry.key;
	END IF;

	INSERT INTO live.changes ("seq", "txid", "version", "table_name", "op", "key", "old", "new", "changed")
	VALUES (
		nextval('live.change_seq'),
		current_txid,
		NULL,
		captured_table,
		left(TG_OP, 1),
		(SELECT jsonb_agg(coalesce(new_row, old_row) -> part.name ORDER BY part.position)
			FROM unnest(key_columns) WITH ORDINALITY AS part(name, position)),
		(SELECT jsonb_object_agg(copied.name, old_row -> copied.name)
			FROM unnest(copied_columns) AS copied(name) WHERE old_row IS NOT NULL),
		(SELECT jsonb_object_agg(copied.name, new_row -> copied.name)
			FROM unnest(copied_columns) AS copied(name) WHERE new_row IS NOT NULL),
		changed_columns
	);

	-- The first write in this transaction registers it for a version at
	-- commit. A transaction-local setting remembers it, rather than reading
	-- the table, which a serializable transaction would conflict through.
	IF current_setting('leptoskit.live_registered', true) IS DISTINCT FROM 'on' THEN
		PERFORM set_config('leptoskit.live_registered', 'on', true);
		INSERT INTO live.pending (txid) VALUES (current_txid);
	END IF;

	RETURN NULL;
END;
$leptoskit$;

CREATE OR REPLACE FUNCTION "live"."seal"() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $leptoskit$
DECLARE
	next_version bigint;
BEGIN
	-- A transaction registers once, so this runs once, even when
	-- `SET CONSTRAINTS ALL IMMEDIATE` runs it before a later write: that
	-- write's change joins the version, which nobody sees before the commit.
	PERFORM pg_advisory_xact_lock(7812448352492680805);
	next_version := nextval('live.version_seq');
	INSERT INTO live.commits (version, txid, committed_at, actor, origin)
	VALUES (
		next_version,
		NEW.txid,
		clock_timestamp(),
		nullif(current_setting('leptoskit.user_id', true), '')::uuid,
		coalesce(nullif(current_setting('leptoskit.origin', true), ''), 'sql')
	);
	PERFORM pg_notify('leptoskit_live', next_version::text);
	RETURN NULL;
END;
$leptoskit$;

