CREATE TRIGGER "live_capture" AFTER INSERT OR UPDATE OR DELETE ON "rewards" FOR EACH ROW EXECUTE FUNCTION "live"."capture"('rewards', 'id', 'id', 'creator_id', 'action_key', 'mint', 'token_symbol', 'decimals', 'amount_per_payout', 'max_payouts', 'max_wins_per_account', 'payouts_reserved', 'payouts_released', 'creator_wallet', 'escrow_address', 'arbiter_address', 'expires_at', 'refund_delay_seconds', 'refund_after', 'status', 'funding_signature', 'funded_at', 'ended_at', 'closed_at', 'created_at', 'updated_at');

