CREATE TRIGGER "live_capture" AFTER INSERT OR UPDATE OR DELETE ON "auth"."sessions" FOR EACH ROW EXECUTE FUNCTION "live"."capture"('auth.sessions', 'id', 'id', 'account_id', 'access_expires_at', 'refreshed_at', 'aal', 'authenticated_at', 'mfa_at', 'last_seen_at', 'idle_expires_at', 'expires_at', 'device', 'revoked_at', 'created_at');

